    """Restore each masked cell from a visible symmetric counterpart."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            # Use the vertical mirror first; then horizontal, then diagonal.
            # The mask can cover several symmetric counterparts at once.
            for rr, cc in ((h - 1 - r, c), (r, w - 1 - c), (c, r)):
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 2:
                    out[r][c] = grid[rr][cc]
                    break
    return out
